@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private void OnSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveLeft(int taskId)
    {
        var task = allTasks.FirstOrDefault(t => t.Id == taskId);
        if (task is null) return;

        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex <= 0) return;

        var newStatus = Statuses[currentIndex - 1];
        await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
        allTasks = allTasks.Select(t => t.Id == taskId ? t with { Status = newStatus } : t).ToList();
    }

    private async Task MoveRight(int taskId)
    {
        var task = allTasks.FirstOrDefault(t => t.Id == taskId);
        if (task is null) return;

        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex >= Statuses.Length - 1) return;

        var newStatus = Statuses[currentIndex + 1];
        await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
        allTasks = allTasks.Select(t => t.Id == taskId ? t with { Status = newStatus } : t).ToList();
    }

    private async Task HandleTaskCreated(AddTaskForm.NewTaskModel model)
    {
        var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
        allTasks.Add(newTask with { Status = model.Status });
    }
}

